import 'package:flutter/material.dart';

class MyStaticText extends StatelessWidget {
	final String textToShow; // Configuration passed by parent

	// Constructor
	const MyStaticText({Key? key, required this.textToShow}) : super(key: key);

	@override
	Widget build(BuildContext context) {
		// Describes the UI for this widget
		return Text(
			textToShow,
				style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
			);
		}
	}

// How to use it:
// MyStaticText(textToShow: "Hello, Flutter!")

